import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const at=file=>fileURLToPath(new URL(file,import.meta.url));
const fn='_M0FP210JingLan0v03stn20feasible__potentials';
const marker='  const values = $make_array_len_and_init(n, 0);';
const cases=['maintenance','independent','first-pair','four-resources','max-root','max-model','tight-impossible'];
for(const driver of ['lookupbench','deepbench']){
 const js=readFileSync(at('base-'+driver+'.js'),'utf8').replaceAll('\r\n','\n');
 const start=js.indexOf('function '+fn+'(');
 const end=js.indexOf('\nfunction ',start+1);
 assert(start>=0&&end>start);
 const body=js.slice(start,end);
 assert.equal(body.split(marker).length,2);
 for(const mode of ['count','init','timer-control','solve']){
  const delta=mode==='count'?'  stats.arrays++;\n  stats.slots+=n;\n'+marker:
   mode==='init'?'  const start = performance.now();\n'+marker+'\n  stats.ms+=performance.now()-start;':
   mode==='timer-control'?'  const start = performance.now();\n  stats.ms+=performance.now()-start;\n'+marker:marker;
  const wrapper=mode==='solve'?'const orig='+fn+';\n'+fn+'=(...args)=>{const start=performance.now();try{return orig(...args)}finally{stats.ms+=performance.now()-start}};\n':'';
  const header="const stats={arrays:0,slots:0,ms:0};\n"+wrapper+
   "process.once('exit',()=>console.error(JSON.stringify(stats)));\n";
  writeFileSync(at('base-'+driver+'-'+mode+'.js'),header+js.slice(0,start)+body.replace(marker,delta)+js.slice(end));
 }
}
const rows=[];
for(const name of cases){
 const deep=name==='tight-impossible';
 const run=mode=>{
  const args=[at('base-'+(deep?'deepbench':'lookupbench')+'-'+mode+'.js'),...(deep?[]:[name])];
  const r=spawnSync(process.execPath,args,{encoding:'utf8',timeout:40000});
  assert.ifError(r.error);
  assert.equal(r.status,0,r.stderr);
  assert.equal(r.stdout.trim().split(/\r?\n/).length,9);
  return JSON.parse(r.stderr);
 };
 const counts=run('count');
 const phase=Object.fromEntries(['init','timer-control','solve'].map(mode=>[mode,[]]));
 for(let pair=0;pair<3;pair++){
  const modes=Object.keys(phase);
  if(pair%2)modes.reverse();
  for(const mode of modes)phase[mode].push(run(mode).ms);
 }
 console.log(name,counts.arrays,counts.slots,JSON.stringify(phase));
 rows.push({name,arrays:counts.arrays,slots:counts.slots,ms:phase});
}
writeFileSync(at('baseline-probe.json'),JSON.stringify(rows,null,2)+'\n');

