import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const at=file=>fileURLToPath(new URL(file,import.meta.url));
const stats="const allocationProbe = {arrays:0,resets:0,initializedSlots:0};\n";
const trail="process.once('exit',()=>console.error(JSON.stringify(allocationProbe)));\n";
const variants=['base','eager','admitted'];
const outputs={};
const rootCase={...JSON.parse(readFileSync(at('base/examples/maintenance-plan.json'))),max_work:1};
for(const variant of variants){
 outputs[variant]={};
 for(const driver of ['main','lookupbench','deepbench']){
  const original=readFileSync(at(variant+'-'+driver+'.js'),'utf8').replaceAll('\r\n','\n');
  const variable={base:'values',eager:'buffer',admitted:'initial'}[variant];
  const marker='const '+variable+' = $make_array_len_and_init(n, 0);';
  assert.equal(original.split(marker).length,2);
  let js=original.replace(marker,'allocationProbe.arrays++; allocationProbe.initializedSlots+=n; '+marker);
  if(variant!=='base'){
   const argument=variant==='eager'?'buffer':'_previous';
   const fill='fill_2einnerGdE('+argument+', 0, 0, undefined);';
   assert.equal(js.split(fill).length,2);
   js=js.replace(fill, fill+' allocationProbe.resets++; allocationProbe.initializedSlots+=n;');
  }
  const file=at(variant+'-'+driver+'-allocations.js');
  writeFileSync(file,stats+js+'\n'+trail);
  const cases=driver==='lookupbench'?['max-model','max-root']:driver==='deepbench'?['tight-impossible']:['root-rejected'];
  for(const name of cases){
   const args=driver==='lookupbench'?[name]:driver==='main'?['--plan-batch','-']:[];
   const input=driver==='main'?JSON.stringify(Array(64).fill(rootCase)):undefined;
   const r=spawnSync(process.execPath,[file,...args],{input,encoding:'utf8',timeout:30000});
   assert.ifError(r.error);
   assert.equal(r.status,0,r.stderr);
   if(input){
    const batch=JSON.parse(r.stdout);
    assert.equal(batch.length,64);
    for(const result of batch){
     assert.equal(result.status,'error');
     assert.equal(result.code,'limit_exceeded');
     assert.match(result.message,/work budget/);
    }
   }else assert.equal(r.stdout.trim().split(/\r?\n/).length,9);
   outputs[variant][name]=JSON.parse(r.stderr);
  }
 }
}
for(const name of ['max-model','max-root','tight-impossible']){
 for(const option of ['eager','admitted']){
  const before=outputs.base[name],after=outputs[option][name];
  assert.equal(after.initializedSlots,before.initializedSlots);
  assert.equal(after.resets+after.arrays,before.arrays);
 }
}
assert.deepEqual(variants.map(v=>outputs[v]['root-rejected'].arrays),[0,64,0]);
console.log(JSON.stringify(outputs,null,2));
writeFileSync(at('variant-counts.json'),JSON.stringify(outputs,null,2)+'\n');

